"""Next Greater Element II — monotonic stack over two laps of the array.

Iterating 2n times simulates the circular wrap without copying the array.

Time: O(n)   Space: O(n)
"""
from typing import List


class Solution:
    def nextGreaterElements(self, nums: List[int]) -> List[int]:
        n = len(nums)
        out, stack = [-1] * n, []
        for i in range(2 * n):
            idx = i % n
            while stack and nums[stack[-1]] < nums[idx]:
                out[stack.pop()] = nums[idx]
            if i < n:
                stack.append(idx)
        return out
